import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing LayerNorm over the last `normalized_shape`
# dimensions (flattened to N elements). Structural optimization: the batch
# dimension B is often far smaller than the number of SMs on the GPU (e.g.
# B=16 vs 128 SMs on an RTX 4090), so launching exactly one CTA per row
# leaves most SMs idle. This version splits each row's N elements across
# multiple cooperating CTAs (grid.y = CHUNKS) that each compute a partial
# sum/sum-of-squares, combine them via global-memory atomics + a spin-wait
# barrier (one "last" CTA per row finalizes mean/inv-std), and then each
# CTA normalizes only its own chunk of the row. This increases the number
# of concurrently resident CTAs (occupied SMs) while preserving identical
# numerics (double-precision accumulation, same formulas) to the reference
# kernel.
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry layernorm_kernel(
    .param .u64 param_X,
    .param .u64 param_Gamma,
    .param .u64 param_Beta,
    .param .u64 param_Y,
    .param .u32 param_B,
    .param .u32 param_N,
    .param .f32 param_eps,
    .param .u64 param_SumBuf,
    .param .u64 param_SumSqBuf,
    .param .u64 param_CounterBuf,
    .param .u64 param_MeanBuf,
    .param .u64 param_InvStdBuf,
    .param .u64 param_FlagBuf
)
{
    .reg .pred %p<24>;
    .reg .b32 %r<140>;
    .reg .f32 %f<8>;
    .reg .f64 %fd<40>;
    .reg .b64 %rd<50>;

    .shared .align 8 .b8 warp_sum[64];
    .shared .align 8 .b8 warp_sumsq[64];
    .shared .align 8 .f64 mean_sh;
    .shared .align 8 .f64 invstd_sh;

    ld.param.u64 %rd1, [param_X];
    ld.param.u64 %rd2, [param_Gamma];
    ld.param.u64 %rd3, [param_Beta];
    ld.param.u64 %rd4, [param_Y];
    ld.param.u32 %r1, [param_B];
    ld.param.u32 %r2, [param_N];
    ld.param.f32 %f1, [param_eps];
    ld.param.u64 %rd20, [param_SumBuf];
    ld.param.u64 %rd21, [param_SumSqBuf];
    ld.param.u64 %rd22, [param_CounterBuf];
    ld.param.u64 %rd23, [param_MeanBuf];
    ld.param.u64 %rd24, [param_InvStdBuf];
    ld.param.u64 %rd25, [param_FlagBuf];

    cvta.to.global.u64 %rd5, %rd1;
    cvta.to.global.u64 %rd6, %rd2;
    cvta.to.global.u64 %rd7, %rd3;
    cvta.to.global.u64 %rd8, %rd4;
    cvta.to.global.u64 %rd26, %rd20;
    cvta.to.global.u64 %rd27, %rd21;
    cvta.to.global.u64 %rd28, %rd22;
    cvta.to.global.u64 %rd29, %rd23;
    cvta.to.global.u64 %rd30, %rd24;
    cvta.to.global.u64 %rd31, %rd25;

    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %tid.x;
    mov.u32 %r60, %ctaid.y;
    mov.u32 %r61, %nctaid.y;

    mul.wide.s32 %rd9, %r3, %r2;
    shl.b64 %rd10, %rd9, 2;
    add.s64 %rd11, %rd5, %rd10;
    add.s64 %rd12, %rd8, %rd10;

    // chunk_size = ceil(N / chunks)
    add.s32 %r62, %r2, %r61;
    sub.s32 %r62, %r62, 1;
    div.u32 %r63, %r62, %r61;

    mul.lo.s32 %r64, %r60, %r63;
    add.s32 %r65, %r64, %r63;
    min.s32 %r66, %r65, %r2;

    mov.f64 %fd1, 0d0000000000000000;
    mov.f64 %fd2, 0d0000000000000000;
    add.s32 %r5, %r4, %r64;

LOOP1:
    setp.ge.s32 %p1, %r5, %r66;
    @%p1 bra LOOP1_END;

    mul.wide.s32 %rd13, %r5, 4;
    add.s64 %rd14, %rd11, %rd13;
    ld.global.f32 %f2, [%rd14];
    cvt.f64.f32 %fd3, %f2;
    add.f64 %fd1, %fd1, %fd3;
    fma.rn.f64 %fd2, %fd3, %fd3, %fd2;
    add.s32 %r5, %r5, 256;
    bra LOOP1;

LOOP1_END:

    mov.u32 %r11, 31;
    mov.u32 %r12, -1;

    // ---- warp-level reduction of (fd1,fd2), offsets 16,8,4,2,1 ----
    mov.b64 {%r13,%r14}, %fd1;
    shfl.sync.down.b32 %r15|%p2, %r14, 16, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 16, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd1, %fd1, %fd4;
    mov.b64 {%r17,%r18}, %fd2;
    shfl.sync.down.b32 %r19|%p4, %r18, 16, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 16, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd2, %fd2, %fd5;

    mov.b64 {%r13,%r14}, %fd1;
    shfl.sync.down.b32 %r15|%p2, %r14, 8, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 8, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd1, %fd1, %fd4;
    mov.b64 {%r17,%r18}, %fd2;
    shfl.sync.down.b32 %r19|%p4, %r18, 8, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 8, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd2, %fd2, %fd5;

    mov.b64 {%r13,%r14}, %fd1;
    shfl.sync.down.b32 %r15|%p2, %r14, 4, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 4, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd1, %fd1, %fd4;
    mov.b64 {%r17,%r18}, %fd2;
    shfl.sync.down.b32 %r19|%p4, %r18, 4, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 4, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd2, %fd2, %fd5;

    mov.b64 {%r13,%r14}, %fd1;
    shfl.sync.down.b32 %r15|%p2, %r14, 2, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 2, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd1, %fd1, %fd4;
    mov.b64 {%r17,%r18}, %fd2;
    shfl.sync.down.b32 %r19|%p4, %r18, 2, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 2, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd2, %fd2, %fd5;

    mov.b64 {%r13,%r14}, %fd1;
    shfl.sync.down.b32 %r15|%p2, %r14, 1, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 1, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd1, %fd1, %fd4;
    mov.b64 {%r17,%r18}, %fd2;
    shfl.sync.down.b32 %r19|%p4, %r18, 1, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 1, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd2, %fd2, %fd5;

    shr.u32 %r30, %r4, 5;
    and.b32 %r31, %r4, 31;

    setp.ne.s32 %p6, %r31, 0;
    @%p6 bra SKIP_STORE;

    shl.b32 %r32, %r30, 3;
    mov.u32 %r33, warp_sum;
    add.s32 %r34, %r33, %r32;
    st.shared.f64 [%r34], %fd1;
    mov.u32 %r35, warp_sumsq;
    add.s32 %r36, %r35, %r32;
    st.shared.f64 [%r36], %fd2;

SKIP_STORE:
    bar.sync 0;

    setp.ne.s32 %p7, %r30, 0;
    @%p7 bra SKIP_FINAL;

    setp.ge.u32 %p8, %r31, 8;
    @%p8 bra USE_ZERO;

    shl.b32 %r37, %r31, 3;
    mov.u32 %r38, warp_sum;
    add.s32 %r39, %r38, %r37;
    ld.shared.f64 %fd6, [%r39];
    mov.u32 %r40, warp_sumsq;
    add.s32 %r41, %r40, %r37;
    ld.shared.f64 %fd7, [%r41];
    bra AFTER_LOAD;

USE_ZERO:
    mov.f64 %fd6, 0d0000000000000000;
    mov.f64 %fd7, 0d0000000000000000;

AFTER_LOAD:

    // ---- cross-warp reduction of (fd6,fd7), offsets 16,8,4,2,1 ----
    mov.b64 {%r13,%r14}, %fd6;
    shfl.sync.down.b32 %r15|%p2, %r14, 16, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 16, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd6, %fd6, %fd4;
    mov.b64 {%r17,%r18}, %fd7;
    shfl.sync.down.b32 %r19|%p4, %r18, 16, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 16, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd7, %fd7, %fd5;

    mov.b64 {%r13,%r14}, %fd6;
    shfl.sync.down.b32 %r15|%p2, %r14, 8, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 8, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd6, %fd6, %fd4;
    mov.b64 {%r17,%r18}, %fd7;
    shfl.sync.down.b32 %r19|%p4, %r18, 8, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 8, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd7, %fd7, %fd5;

    mov.b64 {%r13,%r14}, %fd6;
    shfl.sync.down.b32 %r15|%p2, %r14, 4, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 4, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd6, %fd6, %fd4;
    mov.b64 {%r17,%r18}, %fd7;
    shfl.sync.down.b32 %r19|%p4, %r18, 4, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 4, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd7, %fd7, %fd5;

    mov.b64 {%r13,%r14}, %fd6;
    shfl.sync.down.b32 %r15|%p2, %r14, 2, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 2, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd6, %fd6, %fd4;
    mov.b64 {%r17,%r18}, %fd7;
    shfl.sync.down.b32 %r19|%p4, %r18, 2, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 2, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd7, %fd7, %fd5;

    mov.b64 {%r13,%r14}, %fd6;
    shfl.sync.down.b32 %r15|%p2, %r14, 1, %r11, %r12;
    shfl.sync.down.b32 %r16|%p3, %r13, 1, %r11, %r12;
    mov.b64 %fd4, {%r16,%r15};
    add.f64 %fd6, %fd6, %fd4;
    mov.b64 {%r17,%r18}, %fd7;
    shfl.sync.down.b32 %r19|%p4, %r18, 1, %r11, %r12;
    shfl.sync.down.b32 %r20|%p5, %r17, 1, %r11, %r12;
    mov.b64 %fd5, {%r20,%r19};
    add.f64 %fd7, %fd7, %fd5;

    setp.ne.s32 %p9, %r31, 0;
    @%p9 bra SKIP_FINAL;

    // ---- cross-CTA combine via global-memory atomics (only tid==0) ----
    cvt.s64.s32 %rd32, %r3;
    shl.b64 %rd33, %rd32, 3;
    shl.b64 %rd34, %rd32, 2;
    add.s64 %rd35, %rd26, %rd33;
    add.s64 %rd36, %rd27, %rd33;
    add.s64 %rd37, %rd29, %rd33;
    add.s64 %rd38, %rd30, %rd33;
    add.s64 %rd39, %rd28, %rd34;
    add.s64 %rd40, %rd31, %rd34;

    atom.global.add.f64 %fd20, [%rd35], %fd6;
    atom.global.add.f64 %fd21, [%rd36], %fd7;
    membar.gl;
    atom.global.add.u32 %r70, [%rd39], 1;
    add.s32 %r71, %r70, 1;
    setp.eq.s32 %p12, %r71, %r61;
    @%p12 bra LAST_BLOCK;

WAIT_FLAG:
    ld.volatile.global.u32 %r72, [%rd40];
    setp.eq.u32 %p13, %r72, 1;
    @!%p13 bra WAIT_FLAG;
    membar.gl;
    ld.global.f64 %fd24, [%rd37];
    ld.global.f64 %fd25, [%rd38];
    st.shared.f64 [mean_sh], %fd24;
    st.shared.f64 [invstd_sh], %fd25;
    bra SKIP_FINAL;

LAST_BLOCK:
    ld.global.f64 %fd22, [%rd35];
    ld.global.f64 %fd23, [%rd36];
    cvt.rn.f64.s32 %fd8, %r2;
    div.rn.f64 %fd9, %fd22, %fd8;
    div.rn.f64 %fd10, %fd23, %fd8;
    mul.f64 %fd11, %fd9, %fd9;
    sub.f64 %fd12, %fd10, %fd11;
    setp.lt.f64 %p10, %fd12, 0d0000000000000000;
    selp.f64 %fd13, 0d0000000000000000, %fd12, %p10;
    cvt.f64.f32 %fd14, %f1;
    add.f64 %fd15, %fd13, %fd14;
    rsqrt.approx.f64 %fd16, %fd15;
    st.global.f64 [%rd37], %fd9;
    st.global.f64 [%rd38], %fd16;
    membar.gl;
    mov.u32 %r73, 1;
    st.volatile.global.u32 [%rd40], %r73;
    st.shared.f64 [mean_sh], %fd9;
    st.shared.f64 [invstd_sh], %fd16;

SKIP_FINAL:
    bar.sync 0;

    ld.shared.f64 %fd17, [mean_sh];
    ld.shared.f64 %fd18, [invstd_sh];

    add.s32 %r50, %r4, %r64;

LOOP2:
    setp.ge.s32 %p11, %r50, %r66;
    @%p11 bra LOOP2_END;

    mul.wide.s32 %rd15, %r50, 4;
    add.s64 %rd16, %rd11, %rd15;
    ld.global.f32 %f3, [%rd16];
    cvt.f64.f32 %fd19, %f3;
    sub.f64 %fd26, %fd19, %fd17;
    mul.f64 %fd27, %fd18, %fd26;

    add.s64 %rd17, %rd6, %rd15;
    ld.global.f32 %f4, [%rd17];
    cvt.f64.f32 %fd28, %f4;

    add.s64 %rd18, %rd7, %rd15;
    ld.global.f32 %f5, [%rd18];
    cvt.f64.f32 %fd29, %f5;

    fma.rn.f64 %fd30, %fd27, %fd28, %fd29;
    cvt.rn.f32.f64 %f6, %fd30;

    add.s64 %rd19, %rd12, %rd15;
    st.global.f32 [%rd19], %f6;

    add.s32 %r50, %r50, 256;
    bra LOOP2;

LOOP2_END:
    ret;
}
.visible .entry zero_scratch_kernel(
    .param .u64 param_F64Ptr,
    .param .u32 param_CountF64,
    .param .u64 param_I32Ptr,
    .param .u32 param_CountI32
)
{
    .reg .pred %p<4>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<10>;
    .reg .f64 %fd<2>;
    ld.param.u64 %rd1, [param_F64Ptr];
    ld.param.u32 %r1, [param_CountF64];
    ld.param.u64 %rd2, [param_I32Ptr];
    ld.param.u32 %r2, [param_CountI32];
    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;
    mov.u32 %r3, %ctaid.x;
    mov.u32 %r4, %ntid.x;
    mov.u32 %r5, %tid.x;
    mad.lo.s32 %r6, %r3, %r4, %r5;
    mov.u32 %r7, %nctaid.x;
    mul.lo.s32 %r8, %r7, %r4;
    add.s32 %r9, %r1, %r2;
ZERO_LOOP:
    setp.ge.s32 %p1, %r6, %r9;
    @%p1 bra ZERO_DONE;
    setp.lt.s32 %p2, %r6, %r1;
    @!%p2 bra ZERO_WRITE_I32;
    mul.wide.s32 %rd5, %r6, 8;
    add.s64 %rd6, %rd3, %rd5;
    mov.f64 %fd1, 0d0000000000000000;
    st.global.f64 [%rd6], %fd1;
    bra ZERO_CONT;
ZERO_WRITE_I32:
    sub.s32 %r10, %r6, %r1;
    mul.wide.s32 %rd7, %r10, 4;
    add.s64 %rd8, %rd4, %rd7;
    mov.u32 %r11, 0;
    st.global.u32 [%rd8], %r11;
ZERO_CONT:
    add.s32 %r6, %r6, %r8;
    bra ZERO_LOOP;
ZERO_DONE:
    ret;
}
"""

_KERNEL_NAME = "layernorm_kernel"
_KERNEL_NAME_ZERO = "zero_scratch_kernel"
_THREADS = 256
_CHUNKS = 8  # number of cooperating CTAs per row along grid.y

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    """Look up the compiled entry to make sure the PTX module is valid."""
    module = _get_module()
    module.function(_KERNEL_NAME)
    return module


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a hand-authored PTX kernel launched via
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))
        self.module = _get_module()
        # Cache for scratch buffers keyed by (B, device). Reusing the
        # allocation across calls avoids repeated cudaMalloc/free, and
        # packing the six small per-row scratch arrays into two
        # contiguous tensors (one f64, one i32) fuses the six separate
        # zero-init kernel launches into two, cutting host-side launch
        # overhead (the dominant cost when B is small).
        self._scratch_cache = {}
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        x_c = x.contiguous().to(torch.float32)
        w_c = self.weight.contiguous().to(torch.float32)
        b_c = self.bias.contiguous().to(torch.float32)
        N = w_c.numel()
        assert x_c.numel() % N == 0, "x size must be divisible by normalized_shape size"
        B = x_c.numel() // N
        y = torch.empty_like(x_c)
        # Scratch buffers used for cross-CTA reduction across the CHUNKS
        # cooperating blocks assigned to each row. Packed into two
        # contiguous allocations (one f64, one i32) instead of six
        # separate tensors: allocations are cached/reused across calls,
        # and resetting them to zero requires only two kernel launches
        # instead of six.
        cache_key = (B, x_c.device)
        cached = self._scratch_cache.get(cache_key)
        if cached is None:
            f64_buf = torch.zeros(4 * B, dtype=torch.float64, device=x_c.device)
            i32_buf = torch.zeros(2 * B, dtype=torch.int32, device=x_c.device)
            cached = (f64_buf, i32_buf)
            self._scratch_cache[cache_key] = cached
        else:
            f64_buf, i32_buf = cached
            total_elems = f64_buf.numel() + i32_buf.numel()
            zero_blocks = max(1, (total_elems + _THREADS - 1) // _THREADS)
            self.module.launch(
                _KERNEL_NAME_ZERO,
                (int(zero_blocks), 1, 1),
                (_THREADS, 1, 1),
                [
                    u64(f64_buf.data_ptr()),
                    i32(int(f64_buf.numel())),
                    u64(i32_buf.data_ptr()),
                    i32(int(i32_buf.numel())),
                ],
            )
        sum_buf = f64_buf[0 * B:1 * B]
        sumsq_buf = f64_buf[1 * B:2 * B]
        mean_buf = f64_buf[2 * B:3 * B]
        invstd_buf = f64_buf[3 * B:4 * B]
        counter_buf = i32_buf[0 * B:1 * B]
        flag_buf = i32_buf[1 * B:2 * B]
        stream = torch.cuda.current_stream().cuda_stream

        self.module.launch(
            _KERNEL_NAME,
            (int(B), int(_CHUNKS), 1),
            (_THREADS, 1, 1),
            [
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_c.data_ptr()),
                u64(y.data_ptr()),
                i32(int(B)),
                i32(int(N)),
                f32(float(self.eps)),
                u64(sum_buf.data_ptr()),
                u64(sumsq_buf.data_ptr()),
                u64(counter_buf.data_ptr()),
                u64(mean_buf.data_ptr()),
                u64(invstd_buf.data_ptr()),
                u64(flag_buf.data_ptr()),
            ],
        )

        return y

